\title{Tropical Weight Enumerator Profiles for Binary Linear Codes\\
via Smooth Poincar\'e Primitives}
\author{Harmonic}
\date{2026-06-16}

\begin{document}
\maketitle

\begin{abstract}
The Hamming weight enumerator $W_C(x,y)=\sum_{c\in C}x^{n-\wt(c)}y^{\wt(c)}$ of a
binary linear code is multiplicative under the direct sum (coordinate concatenation)
of codes: $W_{C\oplus D}=W_C\cdot W_D$. We study the \emph{min-plus tropicalization}
of this invariant, in which the generating sum becomes a minimum and the product
becomes a sum. The resulting object, the \emph{tropical weight enumerator}
$\twe_C(t)=\min_{c\in C}\bigl(\wt(c)\cdot t\bigr)$, is a concave, piecewise-linear
function of a single real parameter whose slopes are the codeword weights. Our main
theorem is the \textbf{tropical additivity law} $\twe_{C\oplus D}=\twe_C+\twe_D$, the
exact min-plus mirror of classical multiplicativity, proved for arbitrary block
lengths and all real slopes with no sign hypothesis. We further show that the
\textbf{minimum distance} is itself a tropical quantity, obeying the tropical-addition
($\min$) law $\dist(C\oplus D)=\min(\dist(C),\dist(D))$ under direct sum, yielding a
complete ``tropical dictionary'' for the concatenation operation. Finally,
instantiating on the extended Hamming $[8,4,4]$ code --- the mod-$2$ shadow of the
$E_8$ lattice --- we exhibit a precise \emph{information-loss} phenomenon:
$\twe_{\Hamming}(t)=\min(0,8t)$, so the minimum-distance stratum at weight $4$ is
invisible to the tropical enumerator because $4$ is not a vertex of the lower convex
hull of the weight spectrum $\{0,4,8\}$. This gives a concrete, geometric reason why
the minimum distance must be recorded as a separate invariant.
\end{abstract}

\section{Introduction}

The weight enumerator is the central generating function of coding theory. For a
binary linear code $C\subseteq\F_2^n$, it packages the entire weight distribution into
a single two-variable polynomial and governs duality (the MacWilliams identity), error
probability, and the deep invariant theory of self-dual codes (Gleason's theorem). Its
single most load-bearing structural property --- used implicitly whenever codes are
built by concatenation --- is \emph{multiplicativity under direct sum},
$W_{C\oplus D}=W_C\cdot W_D$.

Tropical (min-plus) mathematics replaces the field operations $(+,\times)$ of the reals
by $(\min,+)$. This deformation turns generating-function sums into minima and products
into sums, and converts polynomial identities into piecewise-linear ones. It is the
algebraic engine behind shortest-path dynamic programming, scheduling, and a large
swath of modern tropical geometry. Applying it to the weight enumerator produces a
one-parameter, piecewise-linear \emph{profile} of a code whose breakpoints and slopes
encode weight data in convex-geometric form.

This paper develops that tropical shadow on top of binary self-dual code primitives ---
the codes arising as mod-$2$ reductions of even unimodular lattices under
Construction~A --- and proves three results: tropical additivity
(Theorem~\ref{thm:add}); the minimum distance as a tropical-$\min$ invariant
(Theorem~\ref{thm:dist}); and information loss on the Hamming code
(Theorem~\ref{thm:hamming}). All results hold for arbitrary block lengths; the proofs
rest only on additivity of Hamming weight under concatenation,
$\wt(a\mathbin{+\!\!+}b)=\wt(a)+\wt(b)$.

\section{Preliminaries and notation}

Throughout, $n,m\in\N$, and a \emph{binary vector of length $n$} is a function
$v:\mathrm{Fin}\,n\to\Z/2\Z$. A \emph{code} is a finite set $C$ of binary vectors; we
work with arbitrary nonempty finite sets and use linearity only where stated.

\begin{definition}[Hamming weight]
The weight of $v:\mathrm{Fin}\,n\to\Z/2\Z$ is $\wt(v)=\bigl|\{i:v(i)=1\}\bigr|$.
\end{definition}

\begin{definition}[Binary inner product]
For $x,y:\mathrm{Fin}\,n\to\Z/2\Z$, $\langle x,y\rangle=\sum_i x(i)\,y(i)\in\Z/2\Z$.
\end{definition}

\begin{definition}[Self-dual code; double evenness]
A code $C$ is \emph{self-dual} if $x\in C\iff(\forall y\in C,\ \langle x,y\rangle=0)$.
A vector $v$ is \emph{doubly even} if $4\mid\wt(v)$.
\end{definition}

\begin{definition}[Direct sum / concatenation]
For codes $C\subseteq(\mathrm{Fin}\,m\to\Z/2\Z)$ and
$D\subseteq(\mathrm{Fin}\,n\to\Z/2\Z)$, their direct sum is
$C\oplus D=\{a\mathbin{+\!\!+}b:a\in C,\ b\in D\}\subseteq(\mathrm{Fin}\,(m+n)\to\Z/2\Z)$,
where $a\mathbin{+\!\!+}b$ is the concatenation whose first $m$ coordinates are $a$ and
last $n$ are $b$.
\end{definition}

\begin{definition}[Classical weight enumerator]
For a code $C$ of length $n$, $W_C(x,y)=\sum_{c\in C}x^{n-\wt(c)}y^{\wt(c)}\in\Z[x,y]$.
\end{definition}

We recall the foundational facts on which our development rests.

\begin{lemma}[Weight additivity]\label{lem:wtadd}
For all $a:\mathrm{Fin}\,m\to\Z/2\Z$ and $b:\mathrm{Fin}\,n\to\Z/2\Z$,
$\wt(a\mathbin{+\!\!+}b)=\wt(a)+\wt(b)$.
\end{lemma}

\begin{proof}
The support of $a\mathbin{+\!\!+}b$ is the disjoint union of the support of $a$
(coordinates $0,\dots,m-1$) and the support of $b$ (coordinates $m,\dots,m+n-1$);
counting over the two blocks gives additivity.
\end{proof}

\begin{lemma}[Block-diagonal inner product]
For $a,c:\mathrm{Fin}\,m\to\Z/2\Z$ and $b,d:\mathrm{Fin}\,n\to\Z/2\Z$,
$\langle a\mathbin{+\!\!+}b,\,c\mathbin{+\!\!+}d\rangle=\langle a,c\rangle+\langle b,d\rangle$.
\end{lemma}

\begin{lemma}[Cardinality and membership]\label{lem:card}
The concatenation map $(a,b)\mapsto a\mathbin{+\!\!+}b$ is injective on $C\times D$, so
$|C\oplus D|=|C|\cdot|D|$; and $z\in C\oplus D\iff\exists a\in C,\exists b\in D,\
z=a\mathbin{+\!\!+}b$.
\end{lemma}

\begin{corollary}[Classical multiplicativity]\label{cor:mult}
$W_{C\oplus D}=W_C\cdot W_D$.
\end{corollary}

\begin{proof}
Expanding the product, each term
$x^{m-\wt(a)}y^{\wt(a)}\cdot x^{n-\wt(b)}y^{\wt(b)}$ equals
$x^{(m+n)-\wt(a\mathbin{+\!\!+}b)}y^{\wt(a\mathbin{+\!\!+}b)}$ by Lemmas~\ref{lem:wtadd}
and~\ref{lem:card}, and the bijection $C\times D\cong C\oplus D$ matches terms.
\end{proof}

\section{The tropical semiring and tropicalization}

\begin{definition}[Min-plus semiring]
The \emph{tropical semiring} is $(\R\cup\{+\infty\},\oplus,\otimes)$ with
$a\oplus b=\min(a,b)$ (additive identity $+\infty$) and $a\otimes b=a+b$
(multiplicative identity $0$). It is an idempotent commutative semiring.
\end{definition}

Tropicalization replaces each sum $\sum$ by $\min$ and each product/exponent by $+$. A
monomial of tropical weight $\wt(c)$ evaluated at a slope $t$ contributes
$\wt(c)\cdot t$; summation over codewords becomes minimization.

\begin{definition}[Tropical weight enumerator]
For a nonempty code $C$ of length $n$ and $t\in\R$,
$\twe_C(t)=\min_{c\in C}\bigl(\wt(c)\cdot t\bigr)$.
\end{definition}

As a function of $t$, $\twe_C$ is the lower envelope of the finite family of lines
$\{t\mapsto w\cdot t:w\in\spec(C)\}$, where $\spec(C)=\{\wt(c):c\in C\}$ is the
\emph{weight spectrum}. It is therefore concave and piecewise linear, with slopes drawn
from $\spec(C)$.

\begin{lemma}[Lower bound]\label{lem:lb}
For every $c\in C$, $\twe_C(t)\le\wt(c)\cdot t$.
\end{lemma}

\begin{lemma}[Attainment]\label{lem:att}
There exists $c\in C$ with $\twe_C(t)=\wt(c)\cdot t$.
\end{lemma}

\begin{lemma}[Certificate]\label{lem:cert}
If $b\le\wt(c)\cdot t$ for all $c\in C$, then $b\le\twe_C(t)$.
\end{lemma}

These are the defining properties of the infimum over a nonempty finite set, and are
the only tools needed below.

\section{Main theorem: tropical additivity under direct sum}

\begin{lemma}[Nonemptiness]
If $C$ and $D$ are nonempty, so is $C\oplus D$.
\end{lemma}

\begin{theorem}[Tropical additivity]\label{thm:add}
For nonempty codes $C\subseteq(\mathrm{Fin}\,m\to\Z/2\Z)$,
$D\subseteq(\mathrm{Fin}\,n\to\Z/2\Z)$, and every $t\in\R$,
\[
\twe_{C\oplus D}(t)=\twe_C(t)+\twe_D(t).
\]
\end{theorem}

\begin{proof}
We prove the two inequalities.

\emph{($\le$)} By attainment (Lemma~\ref{lem:att}) choose $a\in C$ with
$\twe_C(t)=\wt(a)\cdot t$ and $b\in D$ with $\twe_D(t)=\wt(b)\cdot t$. Then
$a\mathbin{+\!\!+}b\in C\oplus D$, and by Lemmas~\ref{lem:lb} and~\ref{lem:wtadd},
\[
\twe_{C\oplus D}(t)\le\wt(a\mathbin{+\!\!+}b)\cdot t
=(\wt(a)+\wt(b))t=\wt(a)t+\wt(b)t=\twe_C(t)+\twe_D(t).
\]

\emph{($\ge$)} By the certificate (Lemma~\ref{lem:cert}) it suffices that
$\twe_C(t)+\twe_D(t)\le\wt(z)\cdot t$ for every $z\in C\oplus D$. Write
$z=a\mathbin{+\!\!+}b$ with $a\in C$, $b\in D$ (Lemma~\ref{lem:card}); then
\[
\wt(z)t=(\wt(a)+\wt(b))t=\wt(a)t+\wt(b)t\ge\twe_C(t)+\twe_D(t),
\]
each summand bounded below by Lemma~\ref{lem:lb}. Antisymmetry gives equality.
\end{proof}

\begin{remark}[No sign hypothesis]
The identity holds for all real $t$. The reason is independence of the two blocks: the
minimizations over the left and right blocks decouple, so
$\min_{a,b}(f(a)+g(b))=(\min_a f(a))+(\min_b g(b))$ unconditionally. This decoupling is
the tropical fingerprint of the classical factorization
$W_{C\oplus D}=W_C\cdot W_D$ (Corollary~\ref{cor:mult}).
\end{remark}

