\section{The minimum distance as a tropical-min invariant}

\begin{definition}[Minimum distance]
For a code $C$ whose set of nonzero codewords $C\setminus\{0\}$ is nonempty,
$\dist(C)=\min_{c\in C,\ c\ne 0}\wt(c)$.
\end{definition}

\begin{lemma}\label{lem:distprop}
\textup{(i)} For every nonzero $c\in C$, $\dist(C)\le\wt(c)$.
\textup{(ii)} If $b\le\wt(c)$ for every nonzero $c\in C$, then $b\le\dist(C)$.
\end{lemma}

\begin{theorem}[Distance is tropical-additive]\label{thm:dist}
Let $C,D$ each contain the zero vector, with at least one nonzero codeword between them.
Then $\dist(C\oplus D)=\min(\dist(C),\dist(D))$.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{($\le$)} A minimal nonzero codeword of $C$ concatenated with the zero vector of
$D$ (or vice versa) is a nonzero codeword of $C\oplus D$ of weight $\dist(C)$
(resp.\ $\dist(D)$); by Lemma~\ref{lem:distprop}(i) and weight additivity,
$\dist(C\oplus D)\le\min(\dist(C),\dist(D))$. \emph{($\ge$)} Any nonzero
$z=a\mathbin{+\!\!+}b$ has a nonzero block; if $a\ne 0$ then
$\wt(z)=\wt(a)+\wt(b)\ge\wt(a)\ge\dist(C)\ge\min(\dist(C),\dist(D))$, and symmetrically
if $b\ne 0$. Lemma~\ref{lem:distprop}(ii) finishes.
\end{proof}

\section{The Hamming code and the information-loss phenomenon}

\begin{definition}
With generator rows $g_0=11111111$, $g_1=00001111$, $g_2=00110011$, $g_3=01010101$, the
\emph{extended Hamming code} is
$\Hamming=\{\sum_i a_i g_i:a\in(\Z/2\Z)^4\}\subseteq(\Z/2\Z)^8$.
\end{definition}

It is a $[8,4,4]$ self-dual doubly-even code with weight enumerator
$W_{\Hamming}(x,y)=x^8+14x^4y^4+y^8$ (one, fourteen, one codewords of weight $0,4,8$;
$1+14+1=16$), spectrum $\spec(\Hamming)=\{0,4,8\}$, and $\dist(\Hamming)=4$.

\begin{theorem}[Tropical enumerator of Hamming]\label{thm:hamming}
For all $t\in\R$, $\twe_{\Hamming}(t)=\min(0,8t)$.
\end{theorem}

\begin{proof}[Proof sketch]
$\twe_{\Hamming}(t)=\min(0\cdot t,4t,8t)=\min(0,4t,8t)$. For $t\ge 0$ the minimum is
$0$; for $t\le 0$ it is $8t\le 4t\le 0$. In both regimes $4t$ is sandwiched, so
$\min(0,4t,8t)=\min(0,8t)$ and the weight-$4$ line never wins.
\end{proof}

\begin{theorem}[Hull characterization of surviving slopes]\label{thm:hull}
A weight $w\in\spec(C)$ is the strict minimizer of
$\{t\mapsto w'\cdot t:w'\in\spec(C)\}$ for some $t$ if and only if
$w\in\{\min\spec(C),\max\spec(C)\}$, i.e.\ $w$ is a vertex of the lower convex hull of
the spectrum.
\end{theorem}

\begin{proof}[Proof sketch]
The lines $w'\cdot t$ pass through the origin. For $t>0$ the minimum is the smallest
weight; for $t<0$ the largest; at $t=0$ all coincide. No intermediate weight is ever the
unique minimizer; for a one-dimensional point set the extremes are exactly the hull
vertices.
\end{proof}

\begin{corollary}[Information loss]
$\twe$ records only the convex hull of the weight spectrum; a minimum distance strictly
between $0$ and the maximal weight is invisible to $\twe$. For $\Hamming$ the interior
point $4$ of $[0,8]$ is erased, though it is the code's minimum distance.
\end{corollary}

By Theorem~\ref{thm:dist}, $\dist(\Hamming\oplus\Hamming)=\min(4,4)=4$, while by
Theorem~\ref{thm:add}, $\twe_{\Hamming\oplus\Hamming}(t)=2\min(0,8t)=\min(0,16t)$; the
length-$16$ code $\Hamming\oplus\Hamming$ (the mod-$2$ shadow of $E_8\oplus E_8$,
$256=16\cdot16$ codewords) keeps minimum distance $4$.

\section{Algorithms}

\textbf{(A) Tropical enumerator evaluation.} Given $C$ and a slope $t$, compute
$\min_{c\in C}\wt(c)\cdot t$ in $O(|C|\cdot n)$, or $O(|C|)$ per query with precomputed
weights.

\textbf{(B) Spectrum-to-hull profile.} Given $\spec(C)=\{w_1<\dots<w_k\}$,
$\twe_C(t)=\min_i w_i t$; by Theorem~\ref{thm:hull} this equals
$\min(w_1 t,\ w_k t)$, computable in $O(k)$ after sorting.

\textbf{(C) Direct-sum composition.} The profile of $C\oplus D$ is the pointwise sum of
the factor profiles (Theorem~\ref{thm:add}) and its distance is $\min(\dist C,\dist D)$
(Theorem~\ref{thm:dist}), composing in $O(1)$ per point without expanding the product
code.

\section{Applications and discussion}

The tropical profile gives a constant-time bookkeeping rule for concatenated code
design, a fast coarse invariant for enumerator inequivalence, and a convex-geometric
reading of self-dual codes in which the Mallows--Sloane bound $d\le4\lfloor n/24\rfloor+4$
appears as a genuinely global (non-additive) obstruction. The development rests only on
weight additivity under concatenation and the universal properties of finite infima, so
it transfers verbatim to $q$-ary linear codes and product codes.

\section{Future directions}

\begin{conjecture}[Tropical hull recovery]
For any nonempty binary code $C\subseteq\F_2^n$, the slopes realized by $\twe_C$ are
exactly the weights that are vertices of the lower convex hull of
$\{(\wt(c),1):c\in C\}$.
\end{conjecture}

\begin{conjecture}[Tropical Gleason / Mallows--Sloane bound]
Every binary doubly-even self-dual code of length $n$ satisfies
$\dist(C)\le4\lfloor n/24\rfloor+4$; by Theorem~\ref{thm:dist} the right-hand side is
non-additive under direct sum, so the bound is a global obstruction (distance-side
analogue of Gleason length divisibility).
\end{conjecture}

Further: a min-plus MacWilliams identity relating $\twe_C$ and $\twe_{C^\perp}$;
$q$-ary tropical profiles; and a multiplicity-refined tropical enumerator recording how
many codewords sit on each surviving hull facet.

